import{_ as s,c as i,o as a,a2 as t}from"./chunks/framework.QTfwLiL8.js";const k=JSON.parse('{"title":"Enhanced Endpoint Discovery with Extensible Advertised Addresses","description":"","frontmatter":{"aliases":["/blog/2025/10/22/enhanced-endpoint-discovery-with-extensible-advertised-addresses"],"authors":[{"avatar":"https://avatars.githubusercontent.com/dnaeon","email":"dnaeon@gmail.com","login":"dnaeon","name":"Marin Atanasov Nikolov"}],"github_repo":"https://github.com/gardener/documentation","github_subdir":"website/blog/2025/10","linkTitle":"Enhanced Endpoint Discovery with Extensible Advertised Addresses","newsSubtitle":"October 22, 2025","params":{"github_branch":"master"},"path_base_for_github_subdir":{"from":"content/blog/2025/10/10-22-extensible-advertised-addresses-for-shoots.md","to":"10-22-extensible-advertised-addresses-for-shoots.md"},"publishdate":"2025-10-22","title":"Enhanced Endpoint Discovery with Extensible Advertised Addresses"},"headers":[],"relativePath":"blog/2025/10/10-22-extensible-advertised-addresses-for-shoots/index.md","filePath":"blog/2025/10/10-22-extensible-advertised-addresses-for-shoots.md","lastUpdated":null}'),n={name:"blog/2025/10/10-22-extensible-advertised-addresses-for-shoots/index.md"};function r(o,e,d,h,l,p){return a(),i("div",null,e[0]||(e[0]=[t(`<h1 id="enhanced-endpoint-discovery-with-extensible-advertised-addresses" tabindex="-1">Enhanced Endpoint Discovery with Extensible Advertised Addresses <a class="header-anchor" href="#enhanced-endpoint-discovery-with-extensible-advertised-addresses" aria-label="Permalink to &quot;Enhanced Endpoint Discovery with Extensible Advertised Addresses&quot;">​</a></h1><p>Gardener has introduced a new feature that enhances the discoverability of services running within a Shoot&#39;s control plane. While the <code>.status.advertisedAddresses</code> field in the <code>Shoot</code> resource has always provided key endpoints like the API server URL, it now supports extension by other components.</p><h3 id="the-challenge-of-endpoint-discovery" tabindex="-1">The Challenge of Endpoint Discovery <a class="header-anchor" href="#the-challenge-of-endpoint-discovery" aria-label="Permalink to &quot;The Challenge of Endpoint Discovery&quot;">​</a></h3><p>Previously, only a default set of addresses, such as the internal and external API server URLs and the service account issuer URL, were published in a Shoot&#39;s status. Endpoints for other essential services deployed in the control plane—like Plutono, Prometheus, or Vali—remained hidden. Discovering these required direct access to the Seed cluster and knowledge of the Shoot&#39;s technical ID, making them inaccessible to end-users and external tooling that only interact with the <code>Shoot</code> resource.</p><h3 id="a-new-standard-for-advertising-endpoints" tabindex="-1">A New Standard for Advertising Endpoints <a class="header-anchor" href="#a-new-standard-for-advertising-endpoints" aria-label="Permalink to &quot;A New Standard for Advertising Endpoints&quot;">​</a></h3><p>To solve this, Gardener now allows any <code>Ingress</code> resource in the Shoot&#39;s control-plane namespace to be advertised in the <code>Shoot</code> status. By applying a simple label, extension developers and operators can make their services easily discoverable.</p><p>When an <code>Ingress</code> resource is labeled with <code>endpoint.shoot.gardener.cloud/advertise=true</code>, Gardener automatically processes it during the next reconciliation. The hostnames found in the <code>Ingress</code>&#39;s TLS configuration are then added as new entries to the <code>.status.advertisedAddresses</code> list.</p><p>For example, to advertise the endpoint for a Plutono dashboard, you would apply the label to its <code>Ingress</code> resource:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --namespace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shoot--</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">projec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">--</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ingress</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plutono</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> endpoint.shoot.gardener.cloud/advertise=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>After the Shoot reconciles, the list of advertised addresses will include a new entry for Plutono. The name is automatically generated to ensure uniqueness, following the pattern <code>ingress/&lt;ingress-name&gt;/&lt;tls-index&gt;/&lt;host-index&gt;</code>.</p><p>A typical list of advertised addresses might look like this after the change:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">external</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://api.my-shoot.external.gardener.cloud</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">internal</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://api.my-shoot.internal.gardener.cloud</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">service-account-issuer</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://discovery.gardener.cloud/projects/my-project/shoots/shoot-id/issuer</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ingress/plutono/0/0</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://gu-my-shoot.ingress.seed.gardener.cloud</span></span></code></pre></div><p>This mechanism provides a standardized way for any component, including custom extensions, to publish its endpoints directly on the <code>Shoot</code> object, making them programmatically discoverable for users and automation.</p><h3 id="future-enhancements" tabindex="-1">Future Enhancements <a class="header-anchor" href="#future-enhancements" aria-label="Permalink to &quot;Future Enhancements&quot;">​</a></h3><p>This feature currently supports <code>Ingress</code> resources, with plans to include support for <code>Gateway</code> resources from the Kubernetes Gateway API in the future.</p><h3 id="find-out-more" tabindex="-1">Find Out More <a class="header-anchor" href="#find-out-more" aria-label="Permalink to &quot;Find Out More&quot;">​</a></h3><p>To learn more about this feature, you can explore the following resources:</p><ul><li><a href="https://youtu.be/GArG1wh2j1o?t=432" target="_blank" rel="noreferrer">Watch the original presentation</a></li><li><a href="https://github.com/gardener/gardener/pull/13043" target="_blank" rel="noreferrer">Review the implementation on GitHub</a></li><li><a href="https://github.com/gardener/gardener/blob/main/docs/development/shoot-advertised-addresses.md" target="_blank" rel="noreferrer">Read the developer documentation</a></li></ul>`,18)]))}const u=s(n,[["render",r]]);export{k as __pageData,u as default};
